        <text x="236" y="456" font-family="'Syne', 'Plus Jakarta Sans', sans-serif" font-weight="900" font-size="280" fill="none" stroke="#ffffff" stroke-width="2" opacity="0.6" letter-spacing="-10">4D</text>

